基本概念 SSM: 由 Spring framework、SpringMVC、Mybatis 三个框架构成, 是经典的 jave web 的开发模式 Spring framework: 核心框架，提供了依赖注入（DI）和面向切面编程（AOP）等功能 SpringMVC: 基于MVC 模式处理 Web 请求和响应，是 Spring framework 中的一个模块 Mybatis: 一个持久层框架，简化了数据库操作 Tomcat: 用于部署和运行 Java Web 应用，即 war 包 Spring Boot: 是基于 Spring framework 的快速开发工具，提供了自动配置、嵌入式服务器等功能，简化了 Spring framework 的开发过程，但并非原有功能增强 SpringTip由于 Spring framework 是核心框架，通常会简称为 Sring ，但叫法上就和 Spring 系列存在混淆，注意区分。
Spring: 一个开源的 Java 平台，包含一系列的产品，用于构建企业级应用
Spring framework: 核心框架，提供了依赖注入（DI）和面向切面编程（AOP）等功能 Spring Boot: 简化了 Spring framework 的开发过程，但并非原有功能增强 Spring Cloud: 提供了一系列的工具和服务，用于构建分布式系统 &hellip;

概念定义： 在程序运行时，序列化与反序列化就是为了将对象属性值进行保存或者加载。
序列化 (Serialization)：将对象转化成字节序列的过程。 反序列化 (Deserialization)：将字节序列转化成对象的过程。 作用：
持久化：将程序运行中的对象信息保存到本地，等需要的时候又能从本地进行对象数据恢复。 网络传输：网络直接传输数据，但是无法直接传输对象。这样就可以想把对的序列化保存到本地，然后将本地序列化数据传输出去。 数据结构转化：对于数据结构相近的两个结构体，就可以通过序列化与反序列化实现两个结构体对象的数据拷贝赋值，就不用去写拷贝构造与拷贝赋值了。 cerealTip只是单纯 Json 序列化与反序列化，推荐 nlohmann介绍cereal是一个开源的（BSD License）、轻量级的、支持C11特性的、仅仅包含头文件实现的、跨平台的C序列化库。它可以将任意的数据类型序列化成不同的表现形式，比如二进制、XML格式或JSON。
库文件：全部为 .hpp 文件 环境：c++11 结构体定义对于需要序列化与反序列化的结构体需要实现 void serialize(Archive &amp;archive) 模板函数，并且要在 archive 指定需要进行序列化的数据。
CPPCollapseCopy// 二进制序列 #include &#34;cereal/archives/binary.hpp&#34; // NOTE - 当使用非基础类型，都需要指定一下 #include &#34;cereal/types/string.hpp&#34; #include &lt;string&gt; struct Tag { std::string TagName; int id; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(TagConfidence, id); } };// 二进制序列 #include &#34;cereal/archives/binary.hpp&#34; // NOTE - 当使用非基础类型，都需要指定一下 #include &#34;cereal/types/string.hpp&#34; #include &lt;string&gt; struct Tag { std::string TagName; int id; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(TagConfidence, id); } };而对于自定义嵌套结构体，也都需要给出序列化操作
CPPCollapseCopy#include &lt;list&gt; #include &lt;string&gt; #include &#34;cereal/archives/binary.hpp&#34; // 使用到的特殊类型 #include &#34;cereal/types/string.hpp&#34; #include &#34;cereal/types/list.hpp&#34; struct Tag { std::string TagName; int id; // 子结构体的序列化 template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(TagConfidence, id); } }; struct TagGroup { std::string TagGroupName; int id; // NOTE - 自定义的子结构体 Tag 也必须实现 void serialize(Archive &amp;archive) std::list&lt;Tag&gt; Tags; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { // NOTE - 数据的传递顺序与 archive 的定义顺序一样 archive(TagGroupName, id, Tags); } };#include &lt;list&gt; #include &lt;string&gt; #include &#34;cereal/archives/binary.hpp&#34; // 使用到的特殊类型 #include &#34;cereal/types/string.hpp&#34; #include &#34;cereal/types/list.hpp&#34; struct Tag { std::string TagName; int id; // 子结构体的序列化 template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(TagConfidence, id); } }; struct TagGroup { std::string TagGroupName; int id; // NOTE - 自定义的子结构体 Tag 也必须实现 void serialize(Archive &amp;archive) std::list&lt;Tag&gt; Tags; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { // NOTE - 数据的传递顺序与 archive 的定义顺序一样 archive(TagGroupName, id, Tags); } };Notecereal 支持几乎所有的标准库类型，但是不支持「原始指针对象」与「引用对象」。原始指针不能用，但是智能指针是可以。
序列化类型 二进制：序列化将数据放入了 ss 流中，反序列化则从 ss 流中将数据读取出来 CPPCollapseCopy// 二进制 #include &#34;cereal/archives/binary.hpp&#34; #include &lt;iostream&gt; #include &lt;sstream&gt; int main(int argc, char const *argv[]) { // 流 std::stringstream ss; // 序列化数据 int a = 10; { // 创建序列化对象 cereal::BinaryOutputArchive archive(ss); // 序列化数据 archive(a); } // 反序列化 int b; { // 创建反序列化对象 cereal::BinaryInputArchive archive(ss); // 反序列化数据 archive(b); } std::cout &lt;&lt; &#34;a : &#34; &lt;&lt; a &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;b : &#34; &lt;&lt; b &lt;&lt; &#34;
&#34;; return 0; }// 二进制 #include &#34;cereal/archives/binary.hpp&#34; #include &lt;iostream&gt; #include &lt;sstream&gt; int main(int argc, char const *argv[]) { // 流 std::stringstream ss; // 序列化数据 int a = 10; { // 创建序列化对象 cereal::BinaryOutputArchive archive(ss); // 序列化数据 archive(a); } // 反序列化 int b; { // 创建反序列化对象 cereal::BinaryInputArchive archive(ss); // 反序列化数据 archive(b); } std::cout &lt;&lt; &#34;a : &#34; &lt;&lt; a &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;b : &#34; &lt;&lt; b &lt;&lt; &#34;
&#34;; return 0; }Terminaltriangle@LEARN:~$ ./a.exea : 10b : 10xml：序列化是将数据保存到 test.xml 文件中，而反序列化则是从 test.xml 中读取数据 CPPCollapseCopy#include &#34;cereal/archives/xml.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;iostream&gt; #include &lt;fstream&gt; int main(int argc, char const *argv[]) { { // 文件输出流 std::ofstream os(&#34;test.xml&#34;); // 序列化数据 int oa = 10; std::string ostr = &#34;fuck&#34;; // 创建序列化对象 cereal::XMLOutputArchive oarchive(os); // 序列化数据 // cereal::make_nvp 可以用来指定 xml 中数据的标签名称 oarchive &amp; cereal::make_nvp(&#34;int&#34;, oa); oarchive &amp; cereal::make_nvp(&#34;str&#34;, ostr); } { // 文件输入流 std::ifstream is(&#34;test.xml&#34;); // 序列化数据 int ia = 0; std::string istr = &#34;&#34;; // 创建反序列化对象 cereal::XMLInputArchive iarchive(is); // 反序列化数据 iarchive(ia, istr); std::cout &lt;&lt; &#34;ia : &#34; &lt;&lt; ia &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;istr : &#34; &lt;&lt; istr &lt;&lt; &#34;
&#34;; } return 0; }#include &#34;cereal/archives/xml.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;iostream&gt; #include &lt;fstream&gt; int main(int argc, char const *argv[]) { { // 文件输出流 std::ofstream os(&#34;test.xml&#34;); // 序列化数据 int oa = 10; std::string ostr = &#34;fuck&#34;; // 创建序列化对象 cereal::XMLOutputArchive oarchive(os); // 序列化数据 // cereal::make_nvp 可以用来指定 xml 中数据的标签名称 oarchive &amp; cereal::make_nvp(&#34;int&#34;, oa); oarchive &amp; cereal::make_nvp(&#34;str&#34;, ostr); } { // 文件输入流 std::ifstream is(&#34;test.xml&#34;); // 序列化数据 int ia = 0; std::string istr = &#34;&#34;; // 创建反序列化对象 cereal::XMLInputArchive iarchive(is); // 反序列化数据 iarchive(ia, istr); std::cout &lt;&lt; &#34;ia : &#34; &lt;&lt; ia &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;istr : &#34; &lt;&lt; istr &lt;&lt; &#34;
&#34;; } return 0; }json：与 xml 类似，序列化是将数据保存到 test.json 文件中，而反序列化则是从 test.json 中读取数据 CPPCollapseCopy#include &#34;cereal/archives/json.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;iostream&gt; #include &lt;fstream&gt; int main(int argc, char const *argv[]) { { // 输出流 std::ofstream os(&#34;test.json&#34;); // 序列化数据 int oa = 10; std::string ostr = &#34;fuck&#34;; // 创建序列化对象 cereal::JSONOutputArchive oarchive(os); // 序列化数据 // cereal::make_nvp 可以用来指定 json 中数据的属性名称 oarchive &amp; cereal::make_nvp(&#34;int&#34;, oa); oarchive &amp; cereal::make_nvp(&#34;str&#34;, ostr); } { // 输入流 std::ifstream is(&#34;test.json&#34;); // 序列化数据 int ia = 0; std::string istr = &#34;&#34;; // 创建反序列化对象 cereal::JSONInputArchive iarchive(is); // 反序列化数据 iarchive(ia, istr); std::cout &lt;&lt; &#34;ia : &#34; &lt;&lt; ia &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;istr : &#34; &lt;&lt; istr &lt;&lt; &#34;
&#34;; } return 0; }#include &#34;cereal/archives/json.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;iostream&gt; #include &lt;fstream&gt; int main(int argc, char const *argv[]) { { // 输出流 std::ofstream os(&#34;test.json&#34;); // 序列化数据 int oa = 10; std::string ostr = &#34;fuck&#34;; // 创建序列化对象 cereal::JSONOutputArchive oarchive(os); // 序列化数据 // cereal::make_nvp 可以用来指定 json 中数据的属性名称 oarchive &amp; cereal::make_nvp(&#34;int&#34;, oa); oarchive &amp; cereal::make_nvp(&#34;str&#34;, ostr); } { // 输入流 std::ifstream is(&#34;test.json&#34;); // 序列化数据 int ia = 0; std::string istr = &#34;&#34;; // 创建反序列化对象 cereal::JSONInputArchive iarchive(is); // 反序列化数据 iarchive(ia, istr); std::cout &lt;&lt; &#34;ia : &#34; &lt;&lt; ia &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;istr : &#34; &lt;&lt; istr &lt;&lt; &#34;
&#34;; } return 0; }RAII 模式cereal::JSONOutputArchive 与 cereal::XMLOutputArchive 均采用 RAII 模式进行设计，这就导致只有 RAII 对象调用构造函数时，才会真正的保存数据文件。
CPPCollapseCopy#include &#34;cereal/archives/json.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;iostream&gt; #include &lt;fstream&gt; int main(int argc, char const *argv[]) { // { // 输出流 std::ofstream os(&#34;test.json&#34;); // 序列化数据 int oa = 10; std::string ostr = &#34;fuck&#34;; // 创建序列化对象 cereal::JSONOutputArchive oarchive(os); // 序列化数据 oarchive &amp; cereal::make_nvp(&#34;int&#34;, oa); oarchive &amp; cereal::make_nvp(&#34;str&#34;, ostr); // } // { // 输入流 std::ifstream is(&#34;test.json&#34;); // 序列化数据 int ia = 0; std::string istr = &#34;&#34;; // 创建反序列化对象 cereal::JSONInputArchive iarchive(is); // 反序列化数据 iarchive(ia, istr); std::cout &lt;&lt; &#34;ia : &#34; &lt;&lt; ia &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;istr : &#34; &lt;&lt; istr &lt;&lt; &#34;
&#34;; // } return 0; }#include &#34;cereal/archives/json.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;iostream&gt; #include &lt;fstream&gt; int main(int argc, char const *argv[]) { // { // 输出流 std::ofstream os(&#34;test.json&#34;); // 序列化数据 int oa = 10; std::string ostr = &#34;fuck&#34;; // 创建序列化对象 cereal::JSONOutputArchive oarchive(os); // 序列化数据 oarchive &amp; cereal::make_nvp(&#34;int&#34;, oa); oarchive &amp; cereal::make_nvp(&#34;str&#34;, ostr); // } // { // 输入流 std::ifstream is(&#34;test.json&#34;); // 序列化数据 int ia = 0; std::string istr = &#34;&#34;; // 创建反序列化对象 cereal::JSONInputArchive iarchive(is); // 反序列化数据 iarchive(ia, istr); std::cout &lt;&lt; &#34;ia : &#34; &lt;&lt; ia &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;istr : &#34; &lt;&lt; istr &lt;&lt; &#34;
&#34;; // } return 0; }TerminalCopy$./a.exeterminate called after throwing an instance of &#39;cereal::RapidJSONException&#39; what(): rapidjson internal assertion failure: IsObject()当一次运行上述程序时，就会抛出异常。因为序列化执行完毕后，oarchive 并没有马上被释放，那么 test.json 也根本没有生成。这就导致反序列化操作读取 test.json 失败（因为根本就没这个文件）。
序列化本质CPPCollapseCopy#include &#34;cereal/archives/binary.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;sstream&gt; struct TestA { int a1; int a2; std::string str; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(a1,a2,str); } }; struct TestB { int b1; int b2; std::string str; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(b1,b2,str); } };#include &#34;cereal/archives/binary.hpp&#34; #include &#34;cereal/types/string.hpp&#34; #include &lt;sstream&gt; struct TestA { int a1; int a2; std::string str; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(a1,a2,str); } }; struct TestB { int b1; int b2; std::string str; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { archive(b1,b2,str); } };对两个结构相似的结构体进行序列化与反序列化
CPPCollapseCopyint main(int argc, char const *argv[]) { // 输出流 std::stringstream ss; { TestA test; test.a1 = 10; test.a2 = 20; test.str = &#34;fuck&#34;; // 创建序列化对象 cereal::BinaryOutputArchive oarchive(ss); oarchive(test); } { TestB test; // 创建序列化对象 cereal::BinaryInputArchive oarchive(ss); oarchive(test); std::cout &lt;&lt; &#34;b1 &#34; &lt;&lt; test.b1 &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;b2 &#34; &lt;&lt; test.b2 &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;str &#34; &lt;&lt; test.str &lt;&lt; &#34;
&#34;; } return 0; }int main(int argc, char const *argv[]) { // 输出流 std::stringstream ss; { TestA test; test.a1 = 10; test.a2 = 20; test.str = &#34;fuck&#34;; // 创建序列化对象 cereal::BinaryOutputArchive oarchive(ss); oarchive(test); } { TestB test; // 创建序列化对象 cereal::BinaryInputArchive oarchive(ss); oarchive(test); std::cout &lt;&lt; &#34;b1 &#34; &lt;&lt; test.b1 &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;b2 &#34; &lt;&lt; test.b2 &lt;&lt; &#34;
&#34;; std::cout &lt;&lt; &#34;str &#34; &lt;&lt; test.str &lt;&lt; &#34;
&#34;; } return 0; }结果为
TerminalCopy$./a.exeb1 10b2 20str fuck修改结构体TestB中序列化函数中变量顺序
CPPCollapseCopystruct TestB { int b1; int b2; std::string str; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { // archive(b1,b2,str); archive(b2); archive(b1); archive(str); } };struct TestB { int b1; int b2; std::string str; template &lt;class Archive&gt; void serialize(Archive &amp;archive) { // archive(b1,b2,str); archive(b2); archive(b1); archive(str); } };TerminalCopy$./a.exeb1 20b2 10str fuckNoteTestB 接收 TestA 数据的顺序发生了变化，这是因为 TestB 中 serialize 定义的变量序列化顺序发生了改变。 序列化与反序列化的本质就是根据用户在 serialize 中定义的变量顺序进行单纯的 memorycpy 。
序列化函数 serialize 函数：可以用于序列化与返序列化
CPPCollapseCopy// ================ 结构体内部 ====================== struct MyClass { int x, y, z; template&lt;class Archive&gt; void serialize(Archive &amp; archive) { archive( x, y, z ); } }; // ================ 结构体外部 ====================== struct MyClass { int x, y, z; }; template&lt;class Archive&gt; void serialize(Archive &amp; archive, MyClass &amp; m) { archive( m.x, m.y, m.z ); }// ================ 结构体内部 ====================== struct MyClass { int x, y, z; template&lt;class Archive&gt; void serialize(Archive &amp; archive) { archive( x, y, z ); } }; // ================ 结构体外部 ====================== struct MyClass { int x, y, z; }; template&lt;class Archive&gt; void serialize(Archive &amp; archive, MyClass &amp; m) { archive( m.x, m.y, m.z ); }save/load 函数：save 负责序列化；load 负责反序列化
CPPCollapseCopy// ================ 结构体内部 ====================== struct MyClass { int x, y, z; // NOTE - const 函数 template&lt;class Archive&gt; void save(Archive &amp; archive) const { archive( x, y, z ); } template&lt;class Archive&gt; void load(Archive &amp; archive) { archive( x, y, z ); } }; // ================ 结构体外部 ====================== struct MyClass { int x, y, z; }; // NOTE - 参数类型必须是 const 的 template&lt;class Archive&gt; void save(Archive &amp; archive, const MyClass &amp; m) { archive( m.x, m.y, m.z ); } template&lt;class Archive&gt; void load(Archive &amp; archive, MyClass &amp; m) { archive( m.x, m.y, m.z ); } // ================ 结构体内部 ====================== struct MyClass { int x, y, z; // NOTE - const 函数 template&lt;class Archive&gt; void save(Archive &amp; archive) const { archive( x, y, z ); } template&lt;class Archive&gt; void load(Archive &amp; archive) { archive( x, y, z ); } }; // ================ 结构体外部 ====================== struct MyClass { int x, y, z; }; // NOTE - 参数类型必须是 const 的 template&lt;class Archive&gt; void save(Archive &amp; archive, const MyClass &amp; m) { archive( m.x, m.y, m.z ); } template&lt;class Archive&gt; void load(Archive &amp; archive, MyClass &amp; m) { archive( m.x, m.y, m.z ); } 最小化序列函数
CPPCollapseCopystruct MyData { double d; template &lt;class Archive&gt; double save_minimal(Archive const &amp; ) const { return d; } template &lt;class Archive&gt; void load_minimal( Archive const &amp;, double const &amp; value ) { d = value; } };struct MyData { double d; template &lt;class Archive&gt; double save_minimal(Archive const &amp; ) const { return d; } template &lt;class Archive&gt; void load_minimal( Archive const &amp;, double const &amp; value ) { d = value; } };定义私有的序列化函数
CPPCollapseCopy// 添加头文件 #include &lt;cereal/access.hpp&gt; class MyCoolClass { private: int secretX; // 给访问权限 friend class cereal::access; template &lt;class Archive&gt; void serialize( Archive &amp; ar ) { ar( secretX ); } };// 添加头文件 #include &lt;cereal/access.hpp&gt; class MyCoolClass { private: int secretX; // 给访问权限 friend class cereal::access; template &lt;class Archive&gt; void serialize( Archive &amp; ar ) { ar( secretX ); } };版本控制
CPPCollapseCopystruct Tag { std::string TagName; std::string TagDescript; }; // 注册版本号 CEREAL_CLASS_VERSION(Tag, CUR_VERSION); // 在序列化函数中获取版本号 template&lt;class Archive&gt; void serialize(Archive &amp;ar, Tag&amp; cls, const unsigned int version) { ar &amp; make_nvp(&#34;TagName&#34;, cls.TagName); // 新版本添加的字段 if (version &gt;= 0x22) { ar &amp; make_nvp(&#34;TagDescript&#34;, cls.TagDescript); } }struct Tag { std::string TagName; std::string TagDescript; }; // 注册版本号 CEREAL_CLASS_VERSION(Tag, CUR_VERSION); // 在序列化函数中获取版本号 template&lt;class Archive&gt; void serialize(Archive &amp;ar, Tag&amp; cls, const unsigned int version) { ar &amp; make_nvp(&#34;TagName&#34;, cls.TagName); // 新版本添加的字段 if (version &gt;= 0x22) { ar &amp; make_nvp(&#34;TagDescript&#34;, cls.TagDescript); } }流设备 istream：常用于接收从键盘输入的数据，例如 std::cin； ostream：常用于将数据输出到屏幕上，例如 std::cout； iostream：继承自 istream 和 ostream 类，因为该类的功能兼两者于一身，既能用于输入，也能用于输出； 文件 ifstream：用于读取文件中的数据； ofstream：用于向文件中写入数据； fstream：兼 ifstream 和 ofstream 类功能于一身，既能读取文件中的数据，又能向文件中写入数据。 类型转换 istringstream：输入 ostringstream：输出 stringstream：两者 Qt 序列化 定义： CPPCollapseCopy#include &lt;QDataStream&gt; #include &lt;QString&gt; #include &lt;QList&gt; #include &lt;QMap&gt; #include &lt;QVector&gt; #include &lt;QDebug&gt; /* ========================== 结构体内部 ========================= */ struct TestA { QList&lt;int&gt; lst; QMap&lt;int,QString&gt; map; std::vector&lt;int&gt; vec; // 序列化 friend QDataStream &amp;operator&lt;&lt;(QDataStream &amp;output , const TestA &amp;dataInfo) { output &lt;&lt; dataInfo.lst &lt;&lt; dataInfo.map ; return output; } // 反序列化 friend QDataStream &amp;operator&gt;&gt;(QDataStream &amp;input , TestA &amp;dataInfo) { input &gt;&gt; dataInfo.lst &gt;&gt; dataInfo.map; return input; } }; /* ========================== 结构体外部 ========================= */ struct TestB { QList&lt;int&gt; lst; QMap&lt;int,QString&gt; map; std::vector&lt;int&gt; vec; }; // 序列化 QDataStream &amp;operator&lt;&lt;(QDataStream &amp;output , const Test