简介ESLint 是一个用于识别和报告 JavaScript/TypeSrcipt 代码中问题的工具。它可以帮助开发者发现潜在的错误、风格问题以及最佳实践。ESLint 可以与各种编辑器和构建工具集成，提供实时反馈和自动化修复功能。
Terminaltriangle@learn$ npm install eslint --save-dev配置ESLint 的配置文件通常命名为 eslint.config.js
JAVASCRIPTCollapseCopy// eslint.config.js import tseslint from &#39;typescript-eslint&#39;; export default tseslint.config({ // 1. 继承官方推荐和 TypeScript 推荐规则 extends: [ &#34;eslint:recommended&#34;, ...tseslint.configs.recommended, ], // 2. 配置语言环境 languageOptions: { parser: tseslint.parser, // 使用 TypeScript 解析器 parserOptions: { project: [&#34;./tsconfig.json&#34;], // 为需要类型信息的规则提供路径 }, }, // 3. 自定义规则 rules: { &#34;no-console&#34;: &#34;warn&#34;, &#34;@typescript-eslint/no-unused-vars&#34;: &#34;error&#34;, }, // 4. 忽略某些文件 ignores: [&#34;dist/**&#34;, &#34;node_modules/**&#34;], });// eslint.config.js import tseslint from &#39;typescript-eslint&#39;; export default tseslint.config({ // 1. 继承官方推荐和 TypeScript 推荐规则 extends: [ &#34;eslint:recommended&#34;, ...tseslint.configs.recommended, ], // 2. 配置语言环境 languageOptions: { parser: tseslint.parser, // 使用 TypeScript 解析器 parserOptions: { project: [&#34;./tsconfig.json&#34;], // 为需要类型信息的规则提供路径 }, }, // 3. 自定义规则 rules: { &#34;no-console&#34;: &#34;warn&#34;, &#34;@typescript-eslint/no-unused-vars&#34;: &#34;error&#34;, }, // 4. 忽略某些文件 ignores: [&#34;dist/**&#34;, &#34;node_modules/**&#34;], });

概念Model View Delegate 是 QML 应用程序的设计理念。
View : qml 的界面程序 Delegate ：展示数据的界面模板，从 Model 读取一项数据，然后显示在 View 上 Model : 数据模型，是一个类似数组的容器，可以是一维或二维。 组件RepeaterQMLCollapseCopyimport QtQuick 2.5 Column { spacing: 2 Repeater { // Model 数据： 0 ~ 10 的数字序列 model: 10 // Delegate 展示 model 的界面模板，通过 index 获取数据 BlueBox { width: 120 height: 32 text: index } } }import QtQuick 2.5 Column { spacing: 2 Repeater { // Model 数据： 0 ~ 10 的数字序列 model: 10 // Delegate 展示 model 的界面模板，通过 index 获取数据 BlueBox { width: 120 height: 32 text: index } } }NoteRepeater 适合展示数据量有限且不会修改的 model。对于大数据集的展示，则应使用 ListView、GridView、Flickable
ListView 高亮 QMLCollapseCopyimport QtQuick 2.5 import &#34;../common&#34; Background { width: 240 height: 300 ListView { id: view anchors.fill: parent anchors.margins: 20 // 只展示 width x height 范围内的内容 clip: true model: 100 delegate: numberDelegate spacing: 5 // 高亮时，展示的组件 highlight: highlightComponent focus: true } Component { id: highlightComponent GreenBox { width: ListView.view.width } } Component { id: numberDelegate Item { width: ListView.view.width height: 40 Text { anchors.centerIn: parent font.pixelSize: 10 text: index } } } }import QtQuick 2.5 import &#34;../common&#34; Background { width: 240 height: 300 ListView { id: view anchors.fill: parent anchors.margins: 20 // 只展示 width x height 范围内的内容 clip: true model: 100 delegate: numberDelegate spacing: 5 // 高亮时，展示的组件 highlight: highlightComponent focus: true } Component { id: highlightComponent GreenBox { width: ListView.view.width } } Component { id: numberDelegate Item { width: ListView.view.width height: 40 Text { anchors.centerIn: parent font.pixelSize: 10 text: index } } } }首尾 QMLCollapseCopyimport QtQuick 2.5 Background { width: 240 height: 300 ListView { anchors.fill: parent anchors.margins: 20 clip: true model: 4 delegate: numberDelegate spacing: 2 // 首 header: headerComponent // 尾 footer: footerComponent } Component { id: headerComponent YellowBox { width: ListView.view.width height: 20 text: &#39;Header&#39; } } Component { id: footerComponent YellowBox { width: ListView.view.width height: 20 text: &#39;Footer&#39; } } Component { id: numberDelegate GreenBox { width: ListView.view.width height: 40 text: &#39;Item #&#39; + index } } }import QtQuick 2.5 Background { width: 240 height: 300 ListView { anchors.fill: parent anchors.margins: 20 clip: true model: 4 delegate: numberDelegate spacing: 2 // 首 header: headerComponent // 尾 footer: footerComponent } Component { id: headerComponent YellowBox { width: ListView.view.width height: 20 text: &#39;Header&#39; } } Component { id: footerComponent YellowBox { width: ListView.view.width height: 20 text: &#39;Footer&#39; } } Component { id: numberDelegate GreenBox { width: ListView.view.width height: 40 text: &#39;Item #&#39; &#43; index } } }GridViewQMLCollapseCopyimport QtQuick 2.5 Background { width: 220 height: 300 GridView { id: view anchors.fill: parent anchors.margins: 20 clip: true model: 100 // 单元格的大小 cellWidth: 45 cellHeight: 45 // delegate 放在 cell 的左上角 delegate: numberDelegate } Component { id: numberDelegate GreenBox { width: 40 height: 40 text: index } } }import QtQuick 2.5 Background { width: 220 height: 300 GridView { id: view anchors.fill: parent anchors.margins: 20 clip: true model: 100 // 单元格的大小 cellWidth: 45 cellHeight: 45 // delegate 放在 cell 的左上角 delegate: numberDelegate } Component { id: numberDelegate GreenBox { width: 40 height: 40 text: index } } }TableViewQMLCollapseCopyTableView { id: view anchors.fill: parent anchors.margins: 20 // 可以控制两个方向 rowSpacing: 5 columnSpacing: 5 clip: true // 展示 c++ 中定义的 table model model: tableModel delegate: cellDelegate Component { id: cellDelegate GreenBox { implicitHeight: 40 implicitWidth: 40 Text { anchors.centerIn: parent text: display } } } }TableView { id: view anchors.fill: parent anchors.margins: 20 // 可以控制两个方向 rowSpacing: 5 columnSpacing: 5 clip: true // 展示 c&#43;&#43; 中定义的 table model model: tableModel delegate: cellDelegate Component { id: cellDelegate GreenBox { implicitHeight: 40 implicitWidth: 40 Text { anchors.centerIn: parent text: display } } } }回调函数QMLCollapseCopyimport QtQuick 2.11 Rectangle { width: 120 height: 300 gradient: Gradient { GradientStop { position: 0.0; color: &#34;#f6f6f6&#34; } GradientStop { position: 1.0; color: &#34;#d7d7d7&#34; } } ListModel { id: actionModel // 从 5.11 开始，可以将函数作为属性，存放到容器中 ListElement { name: &#34;Copenhagen&#34; hello: function(value) { console.log(value + &#34;: You clicked Copenhagen!&#34;); } } ListElement { name: &#34;Helsinki&#34; hello: function(value) { console.log(value + &#34;: Helsinki here!&#34;); } } ListElement { name: &#34;Oslo&#34; hello: function(value) { console.log(value + &#34;: Hei Hei fra Oslo!&#34;); } } ListElement { name: &#34;Stockholm&#34; hello: function(value) { console.log(value + &#34;: Stockholm calling!&#34;); } } } ListView { anchors.fill: parent anchors.margins: 20 clip: true model: actionModel delegate: actionDelegate spacing: 5 focus: true } Component { id: actionDelegate Rectangle { width: ListView.view.width height: 40 color: &#34;#157efb&#34; Text { anchors.centerIn: parent font.pixelSize: 10 text: name } MouseArea { anchors.fill: parent // 调用每个 delegate 对应的回调函数 onClicked: hello(index); } } } }import QtQuick 2.11 Rectangle { width: 120 height: 300 gradient: Gradient { GradientStop { position: 0.0; color: &#34;#f6f6f6&#34; } GradientStop { position: 1.0; color: &#34;#d7d7d7&#34; } } ListModel { id: actionModel // 从 5.11 开始，可以将函数作为属性，存放到容器中 ListElement { name: &#34;Copenhagen&#34; hello: function(value) { console.log(value &#43; &#34;: You clicked Copenhagen!&#34;); } } ListElement { name: &#34;Helsinki&#34; hello: function(value) { console.log(value &#43; &#34;: Helsinki here!&#34;); } } ListElement { name: &#34;Oslo&#34; hello: function(value) { console.log(value &#43; &#34;: Hei Hei fra Oslo!&#34;); } } ListElement { name: &#34;Stockholm&#34; hello: function(value) { console.log(value &#43; &#34;: Stockholm calling!&#34;); } } } ListView { anchors.fill: parent anchors.margins: 20 clip: true model: actionModel delegate: actionDelegate spacing: 5 focus: true } Component { id: actionDelegate Rectangle { width: ListView.view.width height: 40 color: &#34;#157efb&#34; Text { anchors.centerIn: parent font.pixelSize: 10 text: name } MouseArea { anchors.fill: parent // 调用每个 delegate 对应的回调函数 onClicked: hello(index); } } } }

