)=&gt;{ console.log(&#39;new:&#39;,newVal) /* oldVal 会分情况展示 - 修改对象：旧的对象 - 修改属性： newVal 与 oldVal 一样 */ console.log(&#39;old: &#39;,oldVal) }, { deep: true , // 监视对象内部的属性 immediate: true // 界面加载时，马上调用 } ) &lt;/script&gt;reactiveVUECollapseCopy&lt;script lang=&#34;ts&#34; setup name=&#34;Person&#34;&gt; import {reactive, watch} from &#39;vue&#39;; let person = reactive({ name: &#39;test&#39;, age: 10 }) function changePerson(){ Object.assign(person, {name: &#34;11&#34;, age: 18}) } function changeAge(){ person.age++; } /* NOTE - 强制开启 deep */ watch(person, (newVal, oldVal)=&gt;{ console.log(&#39;new:&#39;,newVal) console.log(&#39;old: &#39;,oldVal) } ) &lt;/script&gt;&lt;script lang=&#34;ts&#34; setup name=&#34;Person&#34;&gt; import {reactive, watch} from &#39;vue&#39;; let person = reactive({ name: &#39;test&#39;, age: 10 }) function changePerson(){ Object.assign(person, {name: &#34;11&#34;, age: 18}) } function changeAge(){ person.age&#43;&#43;; } /* NOTE - 强制开启 deep */ watch(person, (newVal, oldVal)=&gt;{ console.log(&#39;new:&#39;,newVal) console.log(&#39;old: &#39;,oldVal) } ) &lt;/script&gt;对象属性VUECollapseCopy&lt;script lang=&#34;ts&#34; setup name=&#34;Person&#34;&gt; import {reactive, watch} from &#39;vue&#39;; let person = reactive({ name: &#39;test&#39;, age: 10 car : { color: &#39;red&#39;, type: &#39;suv&#39; } }) /* 根据 person.age 定义了一个 &#39;getter&#39; 函数 */ watch( ()=&gt; { return person.age }, (newVal, oldVal)=&gt;{ console.log(&#39;new:&#39;,newVal) console.log(&#39;old: &#39;,oldVal) } ) /* NOTE - 默认只监视 person.car 的变化，不会监视 person.car.color ，需要监视子对象的属性时，需要开启 `deep` */ watch( ()=&gt;{ return person.car }, ()=&gt;{}, { deep:true } ) &lt;/script&gt;&lt;script lang=&#34;ts&#34; setup name=&#34;Person&#34;&gt; import {reactive, watch} from &#39;vue&#39;; let person = reactive({ name: &#39;test&#39;, age: 10 car : { color: &#39;red&#39;, type: &#39;suv&#39; } }) /* 根据 person.age 定义了一个 &#39;getter&#39; 函数 */ watch( ()=&gt; { return person.age }, (newVal, oldVal)=&gt;{ console.log(&#39;new:&#39;,newVal) console.log(&#39;old: &#39;,oldVal) } ) /* NOTE - 默认只监视 person.car 的变化，不会监视 person.car.color ，需要监视子对象的属性时，需要开启 `deep` */ watch( ()=&gt;{ return person.car }, ()=&gt;{}, { deep:true } ) &lt;/script&gt;数组VUECollapseCopy&lt;script lang=&#34;ts&#34; setup name=&#34;Person&#34;&gt; import {reactive, ref, watch} from &#39;vue&#39;; let person = reactive({ name: &#39;test&#39;, age: 10 car : { color: &#39;red&#39;, type: &#39;suv&#39; } }) let temp = ref(0) /* NOTE - 可以将多个内容放一起监视 */ watch( [ ()=&gt; person.name, temp ] (newVal, oldVal)=&gt;{ console.log(&#39;new:&#39;,newVal) console.log(&#39;old: &#39;,oldVal) } ) &lt;/script&gt;&lt;script lang=&#34;ts&#34; setup name=&#34;Person&#34;&gt; import {reactive, ref, watch} from &#39;vue&#39;; let person = reactive({ name: &#39;test&#39;, age: 10 car : { color: &#39;red&#39;, type: &#39;suv&#39; } }) let temp = ref(0) /* NOTE - 可以将多个内容放一起监视 */ watch( [ ()=&gt; person.name, temp ] (newVal, oldVal)=&gt;{ console.log(&#39;new:&#39;,newVal) console.log(&#39;old: &#39;,oldVal) } ) &lt;/script&gt;watchEffectwatchEffect 由 vue 框架自动追踪需要监听的「响应式数据」，不再需要像 watch 一样指明待监听对象。
