调用实体封装调用实体封装类 类：std::function 作用：可以对任何可以调用的目标实体进行存储、复制、和调用操作，这些目标实体包括普通函数、Lambda表达式、函数指针、以及其它函数对象等。通过std::function对C++中各种可调用实体（能写成name()进行调用的，本身就能调用的）的封装，形成一个新的可调用的std::function对象；让我们不再纠结那么多的可调用实体。一切变的简单粗暴。 CPPCollapseCopy#include &lt;functional&gt; #include &lt;iostream&gt; using namespace std; // 普通函数 int TestFunc(int a) { return a; } // Lambda表达式 auto lambda = [](int a)-&gt;int{ return a; }; // 仿函数(functor) class Functor { public: int operator()(int a) { return a; } }; // 1.类成员函数 // 2.类静态函数 class TestClass { public: int ClassMember(int a) { return a; } static int StaticMember(int a) { return a; } }; int main() { std::function&lt; int(int)&gt; Functional; // 普通函数 Functional = TestFunc; int result = Functional(10); cout &lt;&lt; &#34;普通函数：&#34;&lt;&lt; result &lt;&lt; endl; // Lambda表达式 Functional = lambda; result = Functional(20); cout &lt;&lt; &#34;Lambda表达式：&#34;&lt;&lt; result &lt;&lt; endl; // 仿函数 Functor testFunctor; Functional = testFunctor; result = Functional(30); cout &lt;&lt; &#34;仿函数：&#34;&lt;&lt; result &lt;&lt; endl; // 类成员函数 TestClass testObj; Functional = std::bind(&amp;TestClass::ClassMember, testObj, std::placeholders::_1); result = Functional(40); cout &lt;&lt; &#34;类成员函数：&#34;&lt;&lt; result &lt;&lt; endl; // 类静态函数 Functional = TestClass::StaticMember; result = Functional(50); cout &lt;&lt; &#34;类静态函数：&#34;&lt;&lt; result &lt;&lt; endl; return 0; }#include &lt;functional&gt; #include &lt;iostream&gt; using namespace std; // 普通函数 int TestFunc(int a) { return a; } // Lambda表达式 auto lambda = [](int a)-&gt;int{ return a; }; // 仿函数(functor) class Functor { public: int operator()(int a) { return a; } }; // 1.类成员函数 // 2.类静态函数 class TestClass { public: int ClassMember(int a) { return a; } static int StaticMember(int a) { return a; } }; int main() { std::function&lt; int(int)&gt; Functional; // 普通函数 Functional = TestFunc; int result = Functional(10); cout &lt;&lt; &#34;普通函数：&#34;&lt;&lt; result &lt;&lt; endl; // Lambda表达式 Functional = lambda; result = Functional(20); cout &lt;&lt; &#34;Lambda表达式：&#34;&lt;&lt; result &lt;&lt; endl; // 仿函数 Functor testFunctor; Functional = testFunctor; result = Functional(30); cout &lt;&lt; &#34;仿函数：&#34;&lt;&lt; result &lt;&lt; endl; // 类成员函数 TestClass testObj; Functional = std::bind(&amp;TestClass::ClassMember, testObj, std::placeholders::_1); result = Functional(40); cout &lt;&lt; &#34;类成员函数：&#34;&lt;&lt; result &lt;&lt; endl; // 类静态函数 Functional = TestClass::StaticMember; result = Functional(50); cout &lt;&lt; &#34;类静态函数：&#34;&lt;&lt; result &lt;&lt; endl; return 0; }注意事项：
将可调用实体变成std::function对象后，对象的传入参数能传递给可调用实体 std::function对象的返回值就是可调用实体的返回值 std::function 的最大作用是实现回调函数的传参 调用绑定bind： 可以预先把指定可调用实体的某些参数绑定到已有的变量，产生一个新的可调用实体。就是预先将「调用实体」与「参数」保存起来，等到要用的时候，再使用调用之前保存的调用实体。
[!note|style:flat] std::bind 的绑定参数全部都是「拷贝类型」，不能传入「引用类型」
非静态成员函数绑定CPPCollapseCopy#include &lt;iostream&gt; #include &lt;functional&gt; using namespace std; class View { public: void onClick(int x, int y) { cout &lt;&lt; &#34;X : &#34; &lt;&lt; x &lt;&lt; &#34;, Y : &#34; &lt;&lt; y &lt;&lt; endl; } }; int main(int argc, const char * argv[]) { View button; function&lt;void(int, int)&gt; clickCallback; // 指向成员函数 clickCallback = std::bind(&amp;View::onClick, // 指定调用实体 button, // 指定一个对象 std::placeholders::_2, // 第二个传入参数占位符号：123 std::placeholders::_1); // 第一个传入参数占位符号：10 // 进行调用 clickCallback(10, 123); return 0; }#include &lt;iostream&gt; #include &lt;functional&gt; using namespace std; class View { public: void onClick(int x, int y) { cout &lt;&lt; &#34;X : &#34; &lt;&lt; x &lt;&lt; &#34;, Y : &#34; &lt;&lt; y &lt;&lt; endl; } }; int main(int argc, const char * argv[]) { View button; function&lt;void(int, int)&gt; clickCallback; // 指向成员函数 clickCallback = std::bind(&amp;View::onClick, // 指定调用实体 button, // 指定一个对象 std::placeholders::_2, // 第二个传入参数占位符号：123 std::placeholders::_1); // 第一个传入参数占位符号：10 // 进行调用 clickCallback(10, 123); return 0; }Note每一个「非静态成员函数」的第一参数其实是当前对象，即 this，在c++中被隐藏了，因为有了这个this参数，所以才能在成员函数中访问类的其他成员变量与成员函数。在python中就很明确
PYTHONCollapseCopyclass Student: # self 就是当前对象指针 def SetName(self,name): self.name = nameclass Student: # self 就是当前对象指针 def SetName(self,name): self.name = name其他调用实体绑定CPPCollapseCopy#include &lt;iostream&gt; #include &lt;functional&gt; using namespace std; int TestFunc(int a, char c, float f) { cout &lt;&lt; a &lt;&lt; endl; cout &lt;&lt; c &lt;&lt; endl; cout &lt;&lt; f &lt;&lt; endl; return a; } int main() { auto bindFunc1 = bind(TestFunc, std::placeholders::_1, &#39;A&#39;, 100.1); bindFunc1(10); cout &lt;&lt; &#34;=================================
&#34;; auto bindFunc2 = bind(TestFunc, std::placeholders::_2, std::placeholders::_1, 100.1); bindFunc2(&#39;B&#39;, 10); cout &lt;&lt; &#34;=================================
&#34;; auto bindFunc3 = bind(TestFunc, std::placeholders::_2, std::placeholders::_3, std::placeholders::_1); bindFunc3(100.1, 30, &#39;C&#39;); return 0; }#include &lt;iostream&gt; #include &lt;functional&gt; using namespace std; int TestFunc(int a, char c, float f) { cout &lt;&lt; a &lt;&lt; endl; cout &lt;&lt; c &lt;&lt; endl; cout &lt;&lt; f &lt;&lt; endl; return a; } int main() { auto bindFunc1 = bind(TestFunc, std::placeholders::_1, &#39;A&#39;, 100.1); bindFunc1(10); cout &lt;&lt; &#34;=================================
&#34;; auto bindFunc2 = bind(TestFunc, std::placeholders::_2, std::placeholders::_1, 100.1); bindFunc2(&#39;B&#39;, 10); cout &lt;&lt; &#34;=================================
&#34;; auto bindFunc3 = bind(TestFunc, std::placeholders::_2, std::placeholders::_3, std::placeholders::_1); bindFunc3(100.1, 30, &#39;C&#39;); return 0; }引用封装由于std::bind()的参数绑定是值传递，而非引用传递，就算输入是引用也会被强制转换为值传递。 为了实现「引用」的绑定传递，就又打了个补丁：std::ref()、std::cref()
CPPCollapseCopy#include &lt;functional&gt; #include &lt;iostream&gt; void f(int&amp; n1, int&amp; n2, const int&amp; n3) { std::cout &lt;&lt; &#34;In function: &#34; &lt;&lt; n1 &lt;&lt; &#39; &#39; &lt;&lt; n2 &lt;&lt; &#39; &#39; &lt;&lt; n3 &lt;&lt; &#39;
